export * as Tunnel from "./tunnel.js";
import { Schema } from "effect";
import { CSR } from "./csr.js";
import { Certificate } from "./certificate.js";
import { Newtype } from "./newtype.js";
export class ID extends Newtype()("TunnelID", Schema.String) {
}
export const Token = Schema.String.pipe(Schema.brand("TunnelToken"));
export class NotFoundError extends Schema.TaggedError()("NotFound", {
    tunnelID: ID,
}) {
}
export class NoCertificateError extends Schema.TaggedError()("NoCertificate", {
    tunnelID: ID,
}) {
}
export class CertificateNotReadyError extends Schema.TaggedError()("CertificateNotReady", { tunnelID: ID, currentState: Schema.String }) {
}
export class InvalidHostnameError extends Schema.TaggedError()("InvalidHostname", { provided: CSR.Hostname, expected: CSR.Hostname }) {
}
export const State = Schema.Literals(["offline", "online"]);
export class Info extends Schema.Class("Tunnel/Info")({
    id: ID,
    hostname: CSR.Hostname,
    state: State,
    certificateID: Certificate.ID.pipe(Schema.optional),
}) {
}
